	severityContrib := 0
	indicatorTypes := make(map[string]bool)
	actors := make(map[string]bool)
	sevRank := 0

	for _, m := range matches {
		if m.adjusted > maxConf {
			maxConf = m.adjusted
		}
		for _, tag := range m.p.entry.Tags {
			if cur, ok := tagFactor[tag]; ok {
				if m.freshness > cur {
					tagFactor[tag] = m.freshness
				}
			} else {
