		severityContrib += severityWeight(m.p.entry.Severity)
		indicatorTypes[m.p.entry.IndicatorType] = true
		actors[m.p.entry.ThreatActor] = true
		if v := severityValue(m.p.entry.Severity); v > sevRank {
			sevRank = v
		}
	}

	tagBonus := 0.0
	for tag, factor := range tagFactor {
		tagBonus += tagBonusValue(tag) * factor
	}

	multiVectorBonus := 0.0
	switch len(indicatorTypes) {
	case 0, 1:
		multiVectorBonus = 0.0
	case 2:
		multiVectorBonus = 25.0
	default:
		multiVectorBonus = 50.0
	}

	actorBonus := 0.0
	switch len(actors) {
	case 0, 1:
		actorBonus = 0.0
	case 2:
		actorBonus = 15.0
	default:
		actorBonus = 30.0
	}

	enrichedScore := riskScore*(1.0+maxConf) + tagBonus + multiVectorBonus + float64(severityContrib) + actorBonus

	outMatches := make([]iocMatchOutput, 0, len(matches))
	for _, m := range matches {
		outMatches = append(outMatches, iocMatchOutput{
			IocID:         m.p.entry.ID,
			Indicator:     m.p.entry.Indicator,
			IndicatorType: m.p.entry.IndicatorType,
			ThreatActor:   m.p.entry.ThreatActor,
			Confidence:    m.p.entry.Confidence,
			Tags:          nonNilStrings(m.p.entry.Tags),
