				}
			}
			if vals, ok := getStringSlice(threat, "compromised_hosts"); ok {
				for _, val := range vals {
					if ip := net.ParseIP(val); ip != nil && a.p.ipNet.Contains(ip) {
						addCIDRCandidate("compromised_hosts", val, i, a)
					}
				}
			}
		case "port":
			if vals, ok := getIntSlice(threat, "ports_scanned"); ok {
				for _, val := range vals {
					if a.p.port == val {
						matchedFields[i]["ports_scanned"] = true
						break
					}
				}
			}
		case "user":
			if val, ok := getString(threat, "user"); ok && a.p.entry.Indicator == val {
				matchedFields[i]["user"] = true
			}
			if vals, ok := getStringSlice(threat, "target_users"); ok {
				for _, val := range vals {
					if a.p.entry.Indicator == val {
						matchedFields[i]["target_users"] = true
						break
					}
				}
			}
		}
	}

	for field, ipMap := range cidrCandidates {
		for _, cands := range ipMap {
			sort.Slice(cands, func(i, j int) bool {
				if cands[i].prefixLen != cands[j].prefixLen {
					return cands[i].prefixLen > cands[j].prefixLen
				}
				if cands[i].base != cands[j].base {
					return cands[i].base > cands[j].base
				}
				return cands[i].iocID < cands[j].iocID
			})
			winner := cands[0].activeIdx
			matchedFields[winner][field] = true
		}
	}

	matches := make([]iocMatchInternal, 0, len(active))
	for i, a := range active {
		if len(matchedFields[i]) == 0 {
			continue
		}
		fields := sortedKeys(matchedFields[i])
		adjusted := a.base * maxFieldMultiplier(fields)
		matches = append(matches, iocMatchInternal{
			p:             a.p,
			base:          a.base,
			freshness:     a.factor,
			adjusted:      adjusted,
			matchedFields: fields,
		})
	}

	sort.SliceStable(matches, func(i, j int) bool {
		if matches[i].adjusted != matches[j].adjusted {
			return matches[i].adjusted > matches[j].adjusted
		}
		return matches[i].p.entry.ID < matches[j].p.entry.ID
	})
	return matches
}

func computeFreshness(p processedIOC, refTime time.Time) (float64, float64, bool) {
	ageHours := refTime.Sub(p.lastUpdated).Hours()
	freshnessFraction := ageHours / float64(p.ttlHours)
	if freshnessFraction >= 1.0 {
		return 0, 0, false
	}
	factor := freshnessFactor(freshnessFraction)
	return p.entry.Confidence * factor, factor, true
}

func freshnessFactor(fraction float64) float64 {
	switch {
	case fraction < 0.25:
		return 1.0
	case fraction < 0.50:
		return 0.9
	case fraction < 0.75:
		return 0.7
	default:
		return 0.5
	}
}

func fieldMultiplier(field string) float64 {
	switch field {
	case "source_ip", "dest_ip", "compromised_hosts", "user":
		return 1.0
	case "dest_ips", "target_users":
		return 0.8
	case "ports_scanned":
		return 0.6
	default:
		return 0.0
	}
}

func maxFieldMultiplier(fields []string) float64 {
	max := 0.0
	for _, f := range fields {
		if m := fieldMultiplier(f); m > max {
			max = m
		}
	}
	return max
}

