func sortEnrichedThreats(threats []map[string]interface{}) {
	sort.SliceStable(threats, func(i, j int) bool {
		a := threats[i]
		b := threats[j]
		ea, _ := getFloat(a, "enriched_risk_score")
		eb, _ := getFloat(b, "enriched_risk_score")
		if ea != eb {
			return ea > eb
		}
		ta := threatSortTime(a)
		tb := threatSortTime(b)
		if !ta.Equal(tb) {
			return ta.Before(tb)
		}
		tta, _ := getString(a, "threat_type")
		ttb, _ := getString(b, "threat_type")
		return tta < ttb
	})
}

func threatSortTime(threat map[string]interface{}) time.Time {
	if tt, ok := getString(threat, "threat_type"); ok && tt == "privilege_escalation" {
		if ts, ok := getString(threat, "timestamp"); ok {
